using System;
using System.Collections;
using UnityEngine;
using UnityEngine.UI;

public enum TransitionType
{
    FadeToBlack,
    Glitch, // Заділ на майбутній хоррор
    Iris // Класичний круглий перехід
}

public class TransitionManager : MonoBehaviour
{
    public static TransitionManager Instance { get; private set; }

    [Header("UI Reference")]
    [SerializeField] private CanvasGroup transitionCanvasGroup; // Має бути Image, що покриває весь екран
    [SerializeField] private Image transitionImage;

    void Awake()
    {
        if (Instance == null)
        {
            Instance = this;
            DontDestroyOnLoad(gameObject); // Щоб менеджер переходів жив між сценами
        }
        else
        {
            Destroy(gameObject);
        }

        if (transitionCanvasGroup != null)
        {
            transitionCanvasGroup.alpha = 0f;
            transitionCanvasGroup.blocksRaycasts = false;
        }
    }

    /// <summary>
    /// Головний метод для виклику переходу екрану.
    /// </summary>
    /// <param name="type">Тип переходу (напр., FadeToBlack).</param>
    /// <param name="duration">Повний час туди й назад (напр., 1 сек = 0.5s туди, 0.5s видимитись).</param>
    /// <param name="onMidpoint">Делегат, що викликається, коли екран повністю чорний (ідеально для телепортацій).</param>
    /// <param name="onComplete">Делегат, що викликається, коли екран знову прозорий (кінець процесу).</param>
    public void PlayTransition(TransitionType type, float duration, Action onMidpoint = null, Action onComplete = null)
    {
        if (transitionCanvasGroup == null)
        {
            Debug.LogWarning("[TransitionManager] No CanvasGroup assigned. Performing instant transition.");
            GameEvents.OnScreenDarkened?.Invoke();
            onMidpoint?.Invoke();
            onComplete?.Invoke();
            return;
        }

        // Запускаємо обраний ефект
        switch (type)
        {
            case TransitionType.FadeToBlack:
                StartCoroutine(FadeRoutine(duration, onMidpoint, onComplete));
                break;
            default:
                StartCoroutine(FadeRoutine(duration, onMidpoint, onComplete));
                break;
        }
    }

    private IEnumerator FadeRoutine(float totalDuration, Action onMidpoint, Action onComplete)
    {
        float halfDuration = totalDuration / 2f;
        transitionCanvasGroup.blocksRaycasts = true;

        // Фаза 1: Затемнення (Fade Out)
        float t = 0f;
        while (t < halfDuration)
        {
            t += Time.deltaTime;
            transitionCanvasGroup.alpha = Mathf.Lerp(0f, 1f, t / halfDuration);
            yield return null;
        }
        transitionCanvasGroup.alpha = 1f;

        // ТОЧКА ЧОРНОГО ЕКРАНУ. Тут ми викликаємо глобальний івент DDA!
        GameEvents.OnScreenDarkened?.Invoke();

        // Викликаємо колбек телепортації, переданий сюди (наприклад, з RespawnSystem)
        onMidpoint?.Invoke();

        // Міні-пауза в темряві для ефекту напруги
        yield return new WaitForSeconds(0.2f);

        // Фаза 2: Просвітлення (Fade In)
        t = 0f;
        while (t < halfDuration)
        {
            t += Time.deltaTime;
            transitionCanvasGroup.alpha = Mathf.Lerp(1f, 0f, t / halfDuration);
            yield return null;
        }
        transitionCanvasGroup.alpha = 0f;
        transitionCanvasGroup.blocksRaycasts = false;

        onComplete?.Invoke();
    }
}

