using UnityEngine;

// Базовий абстрактний клас, який бере на себе УСЮ рутину по буферизації DDA.
// Будь-який діти-спадкоємець просто мають зробити override методу `ApplyDDA(float ddaFactor)`!
public abstract class DynamicObstacleBase : MonoBehaviour, IDynamicObstacle
{
    public string ObstacleId => GetComponent<Obstacle>()?.GetObstacleId() ?? "UnknownID";

    [Header("DDA Base Settings")]
    [SerializeField, Range(0f, 2f)] protected float ddaWeight = 1.0f; // 0 = ніколи не міняти, 1 = стандрат, 2 = гіпер-реакція

    // Тут ми будемо тримати базовий запобіжник від "відкоту полегшення", якщо гравець багато вмирав.
    // Наприклад, scale factor 1.2 не має впасти до 1.05 доки глобальна складність не впаде < 1.0
    protected float ddaProgressTracker = 1f;

    private float pendingDifficultyRatio = 1f;
    private bool hasPendingChanges = false;

    protected virtual void OnEnable()
    {
        DDAManager.RegisterObstacle(this);
        GameEvents.OnScreenDarkened += HandleScreenDarkened;
    }

    protected virtual void OnDisable()
    {
        DDAManager.UnregisterObstacle(this);
        GameEvents.OnScreenDarkened -= HandleScreenDarkened;
    }

    // Реєструє об'єкти від DDAManager, коли знаходиться кластер смертей і т.д.
    public void AdjustDifficulty(float multiplier)
    {
        if (Mathf.Approximately(ddaWeight, 0f)) return; // Об'єкт заблокований для DDA інспектором

        // Знаходимо зважений результат з урахуванням ddaWeight
        float rawFactor = 1f / multiplier;
        float weightedFactor = Mathf.Lerp(1f, rawFactor, ddaWeight);

        // Можна також тут додати перевірку на мінімуми/максимуми,
        // АЛЕ: у швидкості, часу та розміру зовсім різні ліміти.
        // Тому ліміти будемо доручати обрізати самому підкласу. Але ми не дамо 
        // DDA випадково забрати у гравця полегшення!

        if (weightedFactor >= 1f && weightedFactor < ddaProgressTracker)
        {
            return; // Запобіжник від незначного полегшення
        }

        ddaProgressTracker = weightedFactor;

        pendingDifficultyRatio = weightedFactor;
        hasPendingChanges = true;

        Debug.Log($"[DDA Queue] {ObstacleId}: waiting for darkness to apply {pendingDifficultyRatio}.");
    }

    private void HandleScreenDarkened()
    {
        if (!hasPendingChanges) return;

        // Коли екран чорніє, ми застосовуємо зміни ФІЗИЧНО, на льоту!
        ApplyDDA(pendingDifficultyRatio);
        hasPendingChanges = false;

        Debug.Log($"[DDA Atmosphere] {ObstacleId}: changes secretly applied.");
    }

    /// <summary>
    /// Цей метод буде визначати ЯК САМЕ конкретна перешкода застосовує множник до себе.
    /// multiplier = 1 (без змін), multiplier < 1 (складніше/менше час), multiplier > 1 (легше/більший розмір).
    /// </summary>
    protected abstract void ApplyDDA(float multiplier);
}

