using UnityEngine;

public class SimpleDynamicPlatform : MonoBehaviour, IDynamicObstacle
{
    public string ObstacleId => GetComponent<Obstacle>()?.GetObstacleId() ?? "UnknownID";

    [Header("DDA Scaling Bounds")]
    [SerializeField] float minScaleMultiplier = 0.5f; // Наймешний можливий розмір (ускладнення)
    [SerializeField] float maxScaleMultiplier = 2.0f; // Найбільший можливий розмір (полегшення)

    [Header("DDA Influence")]
    [SerializeField, Range(0f, 5f)] float ddaWeight = 1.0f; // 0 = не змінюється ніколи, 1 = нормально, >1 = дуже чутлива до DDA

    private Vector3 originalScale;
    private float currentScaleFactor = 1f;

    // Зберігаємо зміну в буфер, щоб застосувати лише під час затемнення екрану (Screen Fade)
    private float pendingScaleFactor = 1f;
    private bool hasPendingChanges = false;

    void Awake()
    {
        originalScale = transform.localScale;
        pendingScaleFactor = currentScaleFactor;
    }

    void OnEnable()
    {
        DDAManager.RegisterObstacle(this);
        GameEvents.OnScreenDarkened += ApplyPendingChanges;
    }

    void OnDisable()
    {
        DDAManager.UnregisterObstacle(this);
        GameEvents.OnScreenDarkened -= ApplyPendingChanges;
    }

    public void AdjustDifficulty(float multiplier)
    {
        if (Mathf.Approximately(ddaWeight, 0f)) return; // Об'єкт ігнорує DDA

        // Якщо multiplier < 1 (гравець помирає - полегшуємо -> scale > 1) 
        // Якщо multiplier > 1 (гравець домінує - ускладнюємо -> scale < 1)

        // Додаємо власну вагу об'єкту. Тобто (1 / x) буде відхилено від 1 сильніше чи слабше
        float rawScaleFactor = 1f / multiplier;
        float weightedScaleFactor = Mathf.Lerp(1f, rawScaleFactor, ddaWeight);

        // Застосовуємо ліміти! Об'єкт ніколи не стане меншим за min і більшим за max
        float targetScaleFactor = Mathf.Clamp(weightedScaleFactor, minScaleMultiplier, maxScaleMultiplier);

        // Якщо гравець мучився, полегшення ніколи "не відкочується назад" до складнішого,
        // Окрім випадку, коли система ГЛОБАЛЬНО починає ускладнювати рівень (targetScaleFactor < 1)
        if (targetScaleFactor >= 1f && targetScaleFactor < currentScaleFactor)
        {
            return; // Ігноруємо незначне полегшення, якщо вже було закладено велике полегшення
        }

        // Не застосовуємо зміну миттєво, а кладемо в буфер очікування!
        pendingScaleFactor = targetScaleFactor;
        hasPendingChanges = true;

        Debug.Log($"[DDA] {ObstacleId}: scale change scheduled to {pendingScaleFactor} (weighted: {ddaWeight})");
    }

    // Цей метод викличеться ТІЛЬКИ коли екран повністю чорний (див. GameEvents.OnScreenDarkened)
    private void ApplyPendingChanges()
    {
        if (!hasPendingChanges) return;

        currentScaleFactor = pendingScaleFactor;

        transform.localScale = new Vector3(
            originalScale.x * currentScaleFactor, 
            originalScale.y, 
            originalScale.z * currentScaleFactor
        );

        hasPendingChanges = false;
        Debug.Log($"[DDA Atmosphere] {ObstacleId}: scale physically applied in the dark.");
    }
}"}

